// Bundles the Apps Script server (server/apps-script/main.js + engine + curriculum)
// into the single Code.js file Google runs. Used by tools/build.js and by the
// test that runs the real bundle against pretend Google services.
//
// Google calls top-level functions by name, so the bundle is wrapped and the
// entry points are re-declared as plain functions.

import { build } from 'esbuild';

export const ENTRY_POINTS = ['setup', 'speedCheck', 'doGet', 'apiStudent', 'apiTeacher'];

export async function bundleServer() {
  const result = await build({
    entryPoints: [new URL('../server/apps-script/main.js', import.meta.url).pathname],
    bundle: true,
    format: 'iife',
    globalName: 'MathPath',
    target: 'es2019',
    write: false,
    legalComments: 'none',
    charset: 'ascii', // plain characters only, so copying and pasting can't garble anything
  });
  return [
    '// MathPath server for Google Apps Script. GENERATED by tools/build.js; edit the source, not this file.',
    asciiJs(result.outputFiles[0].text),
    ...ENTRY_POINTS.map((f) => `function ${f}(a, b) { return MathPath.${f}(a, b); }`),
    '',
  ].join('\n');
}

// Any character left outside plain ASCII (in comments or regular expressions)
// as a \\uXXXX escape, which means the same thing anywhere in JavaScript.
export function asciiJs(js) {
  return js.replace(/[^\x00-\x7f]/g, (c) => `\\u${c.charCodeAt(0).toString(16).padStart(4, '0')}`);
}
